import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String mode = sc.next();
        Box box;
        if (mode.equals("D")) {
            box = new Box();
        } else {
            int l = sc.nextInt();
            int w = sc.nextInt();
            int h = sc.nextInt();
            box = new Box(l, w, h);
        }
        System.out.println("Volume: " + box.volume());
    }
}

class Box {
    int length;
    int width;
    int height;

    Box() {
        length = 1;
        width = 1;
        height = 1;
    }

    Box(int length, int width, int height) {
        this.length = length;
        this.width = width;
        this.height = height;
    }

    int volume() {
        return length * width * height;
    }
}

